    const entryId = Number(entry?.id || 0) | 0;
    const entryIdentity = String(entry?.identity || entry?.details?.identity || '');
    const key = String(entry?.pinKey || entryIdentity || (entryId > 0 ? `id:${entryId}` : ''));
    if (!key) continue;
    const rec = byPinKey.get(key);
